"""Note120 : copie principale de test avec LEDs de pages MIDI natives."""
import argparse,json,pathlib,re,shutil,subprocess,tempfile
from gen_seq_gen import symbols
ROOT=pathlib.Path(__file__).resolve().parents[1];STAMP='2026-10-18-midi-page-leds-test-3'
def main():
 p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');a=p.parse_args();cross=next(c for c in ('m68k-linux-gnu-','m68k-elf-') if shutil.which(c+'gcc'))
 with tempfile.TemporaryDirectory() as temp:
  d=pathlib.Path(temp);subprocess.run([cross+'gcc','-mcpu=54418','-Os','-ffreestanding','-fno-builtin','-fno-pic','-fno-common','-fno-stack-protector','-fno-asynchronous-unwind-tables','-c',str(ROOT/'tools/machines/midi_lanes/page_leds.c'),'-o',str(d/'x.o')],check=True);(d/'x.ld').write_text('SECTIONS { .text 0 : { *(.text*) *(.rodata*) } . = ALIGN(4); .data : { *(.data*) } . = ALIGN(4); .bss : { *(.bss*) *(COMMON) } . = ALIGN(4); pg_end = .; }');subprocess.run([cross+'ld','--emit-relocs','-T',str(d/'x.ld'),'-o',str(d/'x.elf'),str(d/'x.o')],check=True);subprocess.run([cross+'objcopy','-O','binary',str(d/'x.elf'),str(d/'x.bin')],check=True);sy=symbols(cross,d/'x.elf');raw=(d/'x.bin').read_bytes();raw+=bytes(sy['pg_end']-len(raw));rel=subprocess.check_output([cross+'readelf','-rW',str(d/'x.elf')],text=True);offsets=[int(m.group(1),16) for m in re.finditer(r'^([0-9a-f]+)\s+\S+\s+R_68K_32\b',rel,re.M)];assert all(int.from_bytes(raw[i:i+4],'big')<len(raw) for i in offsets);data=dict(hex=raw.hex(),symbols=sy,reloc=offsets)
 target=ROOT/'docs/flasher-midi-page-leds-test';temp=tempfile.TemporaryDirectory(dir=ROOT/'build') if a.check else None;out=pathlib.Path(temp.name) if temp else target;out.mkdir(exist_ok=True)
 for f in (ROOT/'docs/flasher').iterdir():
  if f.is_file() and f.suffix!='.wav':shutil.copyfile(f,out/f.name)
 for name in ['beat-diagnostic-data.js','beat-diagnostic.js']:shutil.copyfile(ROOT/'docs/flasher-machine-combinations-test'/name,out/name)
 s=(out/'index.html').read_text(encoding='utf-8');s=re.sub(r'<script src="midi-page-leds(?:-data)?\.js\?v=[^"]+"></script>','',s);s=re.sub(r'(?<=\?v=)[\w.-]+',STAMP,s);s=re.sub(r"window.MC_BUILD='[^']+'",f"window.MC_BUILD='{STAMP}'",s);s=s.replace('Modded Cycles — web flasher','Modded Cycles — MIDI page LED test').replace('../assets/release.js?','test-release.js?')
 intro='<p><strong data-l="en">MIDI B-side page LED test.</strong><strong data-l="fr">Test LEDs de pages MIDI B.</strong> <span data-l="en">Outside record mode, all available pages stay lit; the playing page blinks. Record mode keeps the selected page solid and the playing page blinking. Entering B in normal pattern mode inherits A’s selected page. In normal pattern mode, FUNC + PAGE opens length settings: turn DATA to change the shared A/B length, or press PAGE for the next 16-step size (wrapping after 64). per-track mode keeps independent MIDI lane lengths. Includes main 1.88 and optional CPU/CUT diagnostics. Main flasher unchanged.</span><span data-l="fr">Hors enregistrement, toutes les pages disponibles restent allumees ; la page jouee clignote. Enregistrement : page editee fixe, page jouee clignotante. L ouverture de B en mode normal reprend la page selectionnee dans A. Mode normal : FUNC + PAGE ouvre les reglages ; DATA change la longueur commune A/B, PAGE passe au prochain multiple de16 (retour apres64). Mode par piste : longueurs MIDI independantes. Inclut le principal1.88 et les diagnostics CPU/CUT facultatifs. Principal inchange.</span></p>'
 s=s.replace('<main class="wrap fl">','<main class="wrap fl">'+intro).replace('</body>',f'<script src="beat-diagnostic-data.js?v={STAMP}"></script><script src="beat-diagnostic.js?v={STAMP}"></script><script src="midi-page-leds-data.js?v={STAMP}"></script><script src="midi-page-leds.js?v={STAMP}"></script></body>');(out/'index.html').write_text(s,encoding='utf-8');(out/'midi-page-leds-data.js').write_text('window.MCMidiPageLeds='+json.dumps(data,separators=(',',':'))+';\n',encoding='utf-8');shutil.copyfile(ROOT/'tools/web/midi-page-leds.js',out/'midi-page-leds.js')
 (out/'test-release.js').write_text('window.MC_RELEASES='+json.dumps([dict(version='MIDI-page-LED-test.3',date='2026-10-18',changes=[dict(en='B-side page LEDs follow stock record/non-record behavior; normal-mode entry inherits the selected A-side page. Shared A/B normal pattern length is editable from B with FUNC + PAGE, DATA or PAGE in 16-step sizes; per-track mode keeps independent MIDI lengths. Optional diagnostics retained; main unchanged.',fr='B : LEDs de pages selon le mode enregistrement natif ; ouverture en mode normal sur la page selectionnee dans A. Longueur normale A/B editable depuis B par FUNC + PAGE puis DATA ou PAGE par16 ; longueurs MIDI independantes en mode par piste. Diagnostics facultatifs conserves ; principal inchange.')])])+';\n',encoding='utf-8');(out/'BUILD.json').write_text(json.dumps(dict(stamp=STAMP,scope='test-only',base='main1.88',main_unchanged=True),indent=2)+'\n',encoding='utf-8')
 (out/'TEST-NOTES.md').write_text('Test only: outside record mode all available B pages are solid while stopped, with the playing page blinking during playback. Record mode retains selected-page solid / playing-page blink priority. Opening B in normal mode inherits A selected page. In normal scale mode all MIDI lane lengths follow the A-side common pattern length, editable from B through FUNC + PAGE then DATA or PAGE for 16-step sizes; choose per-track scale mode for independent MIDI lane length edits. Only the shared A-side length is changed through its stock setter; notes and MIDI speeds are unchanged. Test switching selected pages while another page plays, short and partial pages, six unequal lengths in per-track mode, exit/re-enter B, and REC. CPU/CUT diagnostic remains optional with repeat + SY. Main 1.88 unchanged.\n',encoding='utf-8')
 for name in ('quick-reference.md','quick-reference-fr.md','shortcut-guide.html'):
  f=out/name;text=f.read_text(encoding='utf-8').replace('Selected page solid, playing page blinking.','Outside record mode all available pages are lit and the playing page blinks. In record mode the selected page stays solid and the playing page blinks. Normal-mode entry inherits A-side selected page.').replace('Page editee fixe, page jouee clignotante.','Hors enregistrement, pages disponibles allumees et page jouee clignotante. En enregistrement, page editee fixe et page jouee clignotante. Ouverture en mode normal sur la page selectionnee dans A.')
  text=text.replace('Normal length follows A-side; per-track mode allows independent MIDI lane lengths.','Normal length is shared with A-side and editable from B: FUNC + PAGE, then DATA for exact length or PAGE for 16-step sizes. Per-track mode keeps independent MIDI lane lengths.').replace('Longueur normale liee a A ; longueurs MIDI independantes en mode par piste.','Longueur normale commune avec A et editable depuis B : FUNC + PAGE, puis DATA ou PAGE par16. Mode par piste : longueurs MIDI independantes.')
  f.write_text(text,encoding='utf-8')
 if a.check:
  for f in out.iterdir():assert f.read_bytes().replace(b'\r\n',b'\n')==(target/f.name).read_bytes().replace(b'\r\n',b'\n'),f.name
 print('PASS MIDI page LED test generator',len(raw),'bytes')
if __name__=='__main__':main()
